#!/usr/bin/env python3
"""Device scanner — detect connected hardware via USB, PCI, and Bluetooth."""

import subprocess
import platform
import re
from typing import Optional


def scan_usb() -> list[dict]:
    """Scan for connected USB devices."""
    devices = []
    system = platform.system()

    if system == "Darwin":
        result = subprocess.run(
            ["system_profiler", "SPUSBDataType", "-xml"],
            capture_output=True, text=True
        )
        # TODO: Parse plist output
        # For now, use ioreg as a simpler alternative
        result = subprocess.run(
            ["ioreg", "-p", "IOUSB", "-l", "-w", "0"],
            capture_output=True, text=True
        )
        for line in result.stdout.split("\n"):
            match = re.search(r'"USB Vendor Name" = "([^"]+)"', line)
            if match:
                vendor = match.group(1)
                devices.append({"bus": "USB", "vendor": vendor})

    elif system == "Linux":
        result = subprocess.run(
            ["lsusb"],
            capture_output=True, text=True
        )
        for line in result.stdout.strip().split("\n"):
            parts = line.split()
            if len(parts) >= 6:
                devices.append({
                    "bus": "USB",
                    "device": f"{parts[1]}:{parts[3].rstrip(':')}",
                    "vendor": parts[5] if len(parts) > 5 else "",
                    "product": " ".join(parts[6:]) if len(parts) > 6 else "",
                })

    return devices


def scan_pci() -> list[dict]:
    """Scan for connected PCI devices."""
    devices = []
    system = platform.system()

    if system == "Darwin":
        result = subprocess.run(
            ["system_profiler", "SPHardwareDataType"],
            capture_output=True, text=True
        )
        # Parse for model identifier
        for line in result.stdout.split("\n"):
            if "Model Identifier:" in line:
                devices.append({
                    "bus": "PCI",
                    "type": "system",
                    "model": line.split(":")[1].strip(),
                })

    elif system == "Linux":
        result = subprocess.run(
            ["lspci"],
            capture_output=True, text=True
        )
        for line in result.stdout.strip().split("\n"):
            parts = line.split(" ", 1)
            if len(parts) >= 2:
                devices.append({
                    "bus": "PCI",
                    "device": parts[0],
                    "description": parts[1],
                })

    return devices


def scan_bluetooth() -> list[dict]:
    """Scan for Bluetooth devices."""
    devices = []
    system = platform.system()

    if system == "Darwin":
        result = subprocess.run(
            ["system_profiler", "SPBluetoothDataType"],
            capture_output=True, text=True
        )
        # TODO: Parse bluetooth device list

    elif system == "Linux":
        result = subprocess.run(
            ["bluetoothctl", "devices"],
            capture_output=True, text=True
        )
        for line in result.stdout.strip().split("\n"):
            parts = line.split(" ", 2)
            if len(parts) >= 3:
                devices.append({
                    "bus": "Bluetooth",
                    "device": parts[1],
                    "name": parts[2],
                })

    return devices


def scan_all(timeout: int = 5) -> list[dict]:
    """Scan all connected devices across all buses."""
    devices = []
    devices.extend(scan_usb())
    devices.extend(scan_pci())
    devices.extend(scan_bluetooth())
    return devices


def identify_device(device_id: str) -> dict:
    """Return unverified candidates, never infer identity from the first match."""
    from .device_db import lookup_device
    return {"query": device_id, "source": "local-catalog",
            "candidates": [item.model_dump() for item in lookup_device(device_id)],
            "identified": False, "flash_eligible": False}


def _detect_capabilities(device_id: str) -> list[str]:
    """Detect capabilities of a device from system info."""
    caps = []

    # Check if it's a USB device
    usb_devices = scan_usb()
    for dev in usb_devices:
        if device_id in str(dev):
            caps.append("usb")
            break

    # Check if it's a network device
    result = subprocess.run(
        ["ifconfig"],
        capture_output=True, text=True
    )
    if device_id in result.stdout:
        caps.append("networking")

    return caps

"""Read-only compatibility access to the validated model catalog.

Package-data writes and inferred repurposing eligibility have been retired.
"""
from sonic.lib.catalog import load_catalog


def load_device_db():
    return load_catalog()


def lookup_device(query):
    query = query.casefold()
    return [d for d in load_catalog().values()
            if query in " ".join([d.id, d.vendor, d.model, d.type]).casefold()]


def get_devices_by_type(dev_type):
    return [d for d in load_catalog().values() if d.type == dev_type]
